data.code:
resource "azurerm_service_plan" "expense" {
  name                = "expense-plan"
  location            = azurerm_resource_group.expense.location
  resource_group_name = azurerm_resource_group.expense.name
  os_type             = "Linux"
  sku_name            = "P1v3"
}

resource "azurerm_linux_web_app" "api" {
  name                = "expense-api"
  location            = azurerm_resource_group.expense.location
  resource_group_name = azurerm_resource_group.expense.name
  service_plan_id     = azurerm_service_plan.expense.id

  app_settings = {
    "WEBSITES_ENABLE_APP_SERVICE_STORAGE" = false
    "ConnectionStrings__DefaultConnection" = data.azurerm_key_vault_secret.db_conn.value
  }
}

resource "azurerm_mssql_server" "expense" {
  name                = "expense-sql-server"
  location            = azurerm_resource_group.expense.location
  resource_group_name = azurerm_resource_group.expense.name
  azuread_administrator {
    login_username = "sqladmin"
    object_id      = data.azurerm_client_config.current.object_id
  }
}
